import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import * as Codec from "../core/res/PwCodec.res.mjs";

// Mapping vectors N=3 (step 2 of specs/006-shared-model/plan.md, part 1): the F4 picture facelet rows
// and the wire-v1 states in test/fixtures/mapping/n3-picture-wire.txt. The fixture is generated by
// scripts/mapping-vectors-n3.jl (facelets -> state). This test goes the other way: it renders every
// state back to facelets from the wire definition and the F1 face-up table, and re-encodes the state
// with the ReScript codec.
const mapping = new URL("./fixtures/mapping/", import.meta.url);
const fixtures = new URL("./fixtures/", import.meta.url);
const read = (base, name) => readFileSync(new URL(name, base), "utf8");
const sha = (text) => createHash("sha256").update(text).digest("hex");
const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
const FACES = "URFDLB";

const f1 = JSON.parse(read(fixtures, "conformance/f1-frames.json"));
const face = Object.fromEntries(f1.faces.map((f) => [f.face, f]));
const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const apply = (o, v) => [0, 1, 2].map((i) => dot(o.slice(3 * i, 3 * i + 3), v));
const transposed = (o) => [0, 1, 2].flatMap((i) => [0, 1, 2].map((j) => o[3 * j + i]));
const faceOf = (normal) => FACES[FACES.split("").findIndex((f) => same(face[f].normal, normal))];
// clockwise quarter turn seen from outside about the unit axis m
const clockwise = (m, v) => cross(v, m).map((x, i) => x + dot(m, v) * m[i]);
const classOf = (row, col) => (row === 1 && col === 1 ? "center" : row === 1 || col === 1 ? "midge" : "corner");

const definition = JSON.parse(read(fixtures, "wire/definition-3.json"));
const rows = read(mapping, "n3-picture-wire.txt")
  .split("\n")
  .filter((line) => line && !line.startsWith("#"))
  .map((line) => {
    const [entry, moves, column, token, facelets, hash, state] = line.split("|");
    return { entry, moves, column, token, facelets, hash, state };
  });
const f4 = read(fixtures, "conformance/f4-3x3-picture.txt")
  .split("\n")
  .filter((line) => line && !line.startsWith("#"))
  .map((line) => {
    const [entry, moves, facelets, token, canonical] = line.split("|");
    return { entry, moves, facelets, token, canonical };
  });
const solvedFacelets = f4.find((r) => r.entry === "4" && r.moves === "").facelets.replaceAll(" ", "");

// Facelet index of a slot on a face: right = up x normal, row 0 toward up.
const faceletAt = (f, position) => {
  const right = cross(face[f].up, face[f].normal);
  const col = dot(position, right) / 2 + 1;
  const row = 1 - dot(position, face[f].up) / 2;
  return { index: 9 * FACES.indexOf(f) + 3 * row + col, row, col };
};
// Home facelet of every sticker and its value: the letter of the solved row at that facelet.
const homeValue = (piece, sticker) => {
  const { index } = faceletAt(faceOf(sticker.normal), piece.home);
  return ALPHABET.indexOf(solvedFacelets[index]);
};

// Facelet string of a state. `fault` plants a wrong transpose or a wrong center twist.
const render = (poses, fault = "") => {
  const byId = Object.fromEntries(poses.map((p) => [p.pieceId, p]));
  const out = Array(54).fill("?");
  for (const piece of definition.pieces) {
    const pose = byId[piece.id];
    const o = fault === "transpose" ? transposed(pose.orientation) : pose.orientation;
    for (const sticker of piece.stickers) {
      const now = faceOf(apply(o, sticker.normal));
      const { index, row, col } = faceletAt(now, pose.position);
      let value = homeValue(piece, sticker);
      if (classOf(row, col) === "center") {
        // twist: clockwise quarter turns from the reference direction of the current face to O.u0
        const m = face[now].normal;
        const target = apply(o, sticker.up);
        let w = face[now].up;
        let r = 0;
        while (!same(w, target) && r < 4) {
          w = clockwise(m, w);
          r++;
        }
        assert.equal(r < 4, true, `${piece.id}: O.u0 is not in the plane of the face`);
        if (fault === "twist") r = (r + 1) % 4;
        value = 4 * FACES.indexOf(faceOf(sticker.normal)) + r;
      }
      out[index] = ALPHABET[value];
    }
  }
  return out.join("");
};
const decoded = (row) => JSON.parse(row.state).poses;

test("provenance: input and output hashes, pinned origin, license", () => {
  const prov = read(mapping, "n3-picture-wire.provenance");
  const get = (key) => prov.split("\n").filter((l) => l.startsWith(key + "=")).map((l) => l.slice(key.length + 1));
  assert.deepEqual(get("input_path"), ["test/fixtures/conformance/f4-3x3-picture.txt", "test/fixtures/wire/definition-3.json"]);
  const inputs = get("input_path").map((p) => sha(readFileSync(new URL("../" + p, import.meta.url))));
  assert.deepEqual(get("input_sha256"), inputs);
  assert.deepEqual(get("output_sha256"), [sha(read(mapping, "n3-picture-wire.txt"))]);
  assert.match(get("origin_commit")[0], /^[0-9a-f]{40}$/);
  assert.match(get("license")[0], /^AGPL-3\.0-or-later/);
  assert.equal(get("regenerate")[0], "julia scripts/mapping-vectors-n3.jl check");
});

test("every F4 row and its canonical column has a state row, with the facelets of F4", () => {
  const expected = f4.flatMap((r) => [["facelets", r.facelets], ["canonical", r.canonical]].filter(([, f]) => f).map(([column, f]) => ({ ...r, column, facelets: f })));
  assert.equal(f4.length, 82);
  assert.equal(rows.length, expected.length);
  expected.forEach((e, i) => {
    assert.deepEqual([rows[i].entry, rows[i].moves, rows[i].column, rows[i].token, rows[i].facelets], [e.entry, e.moves, e.column, e.token, e.facelets], `row ${i}`);
  });
});

test("every state is canonical wire-v1, matches its hash and passes the structural checks of the codec", () => {
  const def = Codec.decodeDefinition(read(fixtures, "wire/definition-3.json"));
  assert.equal(def.TAG, "Ok");
  for (const row of rows) {
    const state = Codec.decodeState(def._0, row.state);
    assert.equal(state.TAG, "Ok", `${row.entry} ${row.moves} ${row.column}: ${JSON.stringify(state)}`);
    assert.equal(Codec.encodeState(state._0), row.state, "canonical bytes");
    assert.equal(row.hash, "sha256:" + sha(row.state));
    assert.equal(Codec.hashState(state._0), row.hash);
  }
});

test("rendering each state gives back the facelets of its F4 row", () => {
  for (const row of rows) {
    assert.equal(render(decoded(row)), row.facelets.replaceAll(" ", ""), `${row.entry} ${row.moves} ${row.column}`);
  }
});

test("the solved rows are the home state; whole-cube rows carry the F4 rotation in every pose", () => {
  const home = Codec.homeState(Codec.decodeDefinition(read(fixtures, "wire/definition-3.json"))._0);
  for (const row of rows.filter((r) => r.moves === "" && r.column === "facelets")) assert.equal(row.state, Codec.encodeState(home));
  const f4rot = JSON.parse(read(fixtures, "conformance/f4-3x3-picture-rotations.json"));
  for (const w of f4rot.rotations) {
    const row = rows.find((r) => r.entry === "5" && r.moves === w.word && r.column === "facelets");
    for (const pose of decoded(row)) assert.deepEqual(pose.orientation, w.o, `${w.word} ${pose.pieceId}`);
  }
});

test("quarter turns and 120 degree rotations are in the set, and a wrong transpose or center twist is caught", () => {
  const nonSymmetric = rows.filter((r) => decoded(r).some((p) => !same(p.orientation, transposed(p.orientation))));
  assert(nonSymmetric.length >= 20, `${nonSymmetric.length} rows with O different from its transpose`);
  const framed = rows.filter((r) => r.entry === "5" && ["x", "y", "z", "x'", "y'", "z'"].includes(r.moves));
  assert.equal(framed.length, 6);
  for (const row of nonSymmetric) {
    assert.notEqual(render(decoded(row), "transpose"), row.facelets.replaceAll(" ", ""), `transpose: ${row.entry} ${row.moves}`);
  }
  for (const row of rows) {
    assert.notEqual(render(decoded(row), "twist"), row.facelets.replaceAll(" ", ""), `twist: ${row.entry} ${row.moves}`);
  }
});
